package org.dromara.ai.workspace;
import lombok.RequiredArgsConstructor;
import org.dromara.ai.workspace.runtime.*;
import org.dromara.common.json.utils.JsonUtils;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.beans.factory.annotation.Value;
import java.math.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.MessageDigest;
import java.time.Instant;
import java.util.*;
@Service
@RequiredArgsConstructor
public class WorkspaceTools {
 private final JdbcTemplate jdbc;private final TransactionTemplate tx;private final WorkspaceConversations conversations;private final WorkspaceToolAccess access;private final WorkspaceEvents events;private final AgentRuntime runtime;
 @Value("${workspace.secret-key-file}") private String secretKeyFile;
 public static String hash(String text){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(text.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException();}}
 private String arguments(Map<String,Object> tool,Map<String,Object> args){if(args==null)throw new WorkspaceDenied(400,"ToolArgumentsRequired");if("TEXT_DOCUMENT".equals(tool.get("type"))){if(!args.keySet().equals(Set.of("filename","content"))||!(args.get("filename") instanceof String name)||!name.matches("[\\p{L}\\p{N} _-]{1,90}\\.(txt|md|csv|json)")||!(args.get("content") instanceof String content)||content.isEmpty()||content.getBytes(StandardCharsets.UTF_8).length>65536)throw new WorkspaceDenied(400,"InvalidDocumentArguments");}else{if(!args.keySet().equals(Set.of("operation","a","b"))||!Set.of("add","subtract","multiply","divide").contains(args.get("operation"))||!(args.get("a") instanceof String a)||!(args.get("b") instanceof String b)||!a.matches("-?[0-9]{1,30}(\\.[0-9]{1,12})?")||!b.matches("-?[0-9]{1,30}(\\.[0-9]{1,12})?"))throw new WorkspaceDenied(400,"InvalidCalculatorArguments");}return JsonUtils.toJsonString(new TreeMap<>(args));}
 public Map<String,Object> request(String grant,UUID id,UUID resource,String call,Map<String,Object> args,String digest){return tx.execute(status->{var run=conversations.checkGrant(grant,true);var tool=access.selected(run,resource);String canonical=arguments(tool,args);if(!Boolean.TRUE.equals(tool.get("requiresApproval"))||id==null||call==null||call.length()>200||!hash(canonical).equals(digest))throw new WorkspaceDenied(400,"InvalidApprovalRequest");UUID runId=(UUID)run.get("id"),session=(UUID)run.get("session_id");jdbc.queryForObject("SELECT id FROM ai_run WHERE id=? FOR UPDATE",UUID.class,runId);conversations.checkGrant(grant,true);var old=jdbc.queryForList("SELECT id,args_hash FROM ai_tool_approval WHERE run_id=? AND call_id=?",runId,call);if(!old.isEmpty()){if(!id.equals(old.getFirst().get("id"))||!digest.equals(old.getFirst().get("args_hash")))throw new WorkspaceDenied(409,"ApprovalConflict");return Map.of("id",id.toString());}jdbc.update("INSERT INTO ai_tool_approval(id,run_id,resource_id,call_id,args_hash,arguments) VALUES(?,?,?,?,?,?::jsonb)",id,runId,resource,call,digest,canonical);jdbc.update("UPDATE ai_run SET status='WAITING_APPROVAL' WHERE id=?",runId);var payload=Map.of("id",id.toString(),"tool",tool.get("type"),"filename",args.get("filename"),"content",args.get("content"),"expiresAt",Instant.now().plusSeconds(120).toString());events.append(session,runId,UUID.randomUUID(),"approval.requested",payload);return Map.of("id",id.toString());});}
 public Map<String,Object> decide(UUID session,UUID id,WorkspacePrincipal.Actor actor,boolean approve){conversations.authorizeSession(session,actor);Map<String,Object> result=tx.execute(status->{var runIds=jdbc.queryForList("SELECT r.id FROM ai_run r JOIN ai_tool_approval a ON a.run_id=r.id WHERE a.id=? AND r.session_id=? AND r.owner_user_id=? FOR UPDATE OF r",UUID.class,id,session,actor.userId());if(runIds.size()!=1)throw new WorkspaceDenied(404,"ApprovalNotFound");var rows=jdbc.queryForList("SELECT a.*,r.owner_user_id,r.session_id FROM ai_tool_approval a JOIN ai_run r ON r.id=a.run_id WHERE a.id=? AND r.session_id=? AND r.owner_user_id=? FOR UPDATE OF a",id,session,actor.userId());if(rows.size()!=1)throw new WorkspaceDenied(404,"ApprovalNotFound");var a=rows.getFirst();UUID run=(UUID)a.get("run_id");String grant=conversations.activeGrant(run);if(!"PENDING".equals(a.get("status")))return Map.<String,Object>of("status",a.get("status"),"grant",grant,"dispatch",false);boolean expired=((java.sql.Timestamp)a.get("expires_at")).toInstant().isBefore(Instant.now());String state=expired?"EXPIRED":approve?"APPROVED":"DENIED";jdbc.update("UPDATE ai_tool_approval SET status=?,decided_at=NOW() WHERE id=?",state,id);jdbc.update("UPDATE ai_run SET status='RUNNING' WHERE id=? AND status='WAITING_APPROVAL'",run);events.append(session,run,UUID.randomUUID(),"approval.decided",Map.of("id",id.toString(),"status",state));return Map.<String,Object>of("status",state,"grant",grant,"dispatch",true);});if(Boolean.TRUE.equals(result.get("dispatch"))){try{if("APPROVED".equals(result.get("status")))runtime.approve(result.get("grant").toString(),id);else runtime.deny(result.get("grant").toString(),id);}catch(Exception e){conversations.abortRun(session,actor,"ApprovalDeliveryFailed");throw new WorkspaceDenied(503,"ApprovalDeliveryFailed");}}return Map.of("id",id.toString(),"status",result.get("status"));}
 public Map<String,Object> execute(String grant,UUID resource,String call,Map<String,Object> args,UUID approval){if(call==null||call.isBlank()||call.length()>200)throw new WorkspaceDenied(400,"InvalidToolCall");return tx.execute(status->{var run=conversations.checkGrant(grant,true);UUID id=(UUID)run.get("id");jdbc.queryForObject("SELECT id FROM ai_run WHERE id=? FOR UPDATE",UUID.class,id);conversations.checkGrant(grant,true);var tool=access.selected(run,resource);String canonical=arguments(tool,args),digest=hash(canonical);var old=jdbc.queryForList("SELECT resource_id,args_hash,result::text FROM ai_tool_execution WHERE run_id=? AND call_id=?",id,call);if(!old.isEmpty()){if(!resource.equals(old.getFirst().get("resource_id"))||!digest.equals(old.getFirst().get("args_hash")))throw new WorkspaceDenied(409,"ToolIdempotencyConflict");return JsonUtils.parseMap(old.getFirst().get("result").toString());}
  Map<String,Object> result;if("CALCULATOR".equals(tool.get("type"))){BigDecimal a=new BigDecimal(args.get("a").toString()),b=new BigDecimal(args.get("b").toString());try{BigDecimal value=switch(args.get("operation").toString()){case "add"->a.add(b);case "subtract"->a.subtract(b);case "multiply"->a.multiply(b);default->a.divide(b,((Number)tool.get("precision")).intValue(),RoundingMode.HALF_UP);};result=Map.of("value",value.stripTrailingZeros().toPlainString(),"rounding","HALF_UP","precision",tool.get("precision"));}catch(ArithmeticException e){throw new WorkspaceDenied(400,"DivisionByZero");}}
  else{if(approval==null||jdbc.update("UPDATE ai_tool_approval SET status='CONSUMED' WHERE id=? AND run_id=? AND resource_id=? AND call_id=? AND args_hash=? AND status='APPROVED' AND expires_at>NOW()",approval,id,resource,call,digest)!=1)throw new WorkspaceDenied(403,"ApprovalRequired");UUID artifact=UUID.randomUUID();byte[] bytes=args.get("content").toString().getBytes(StandardCharsets.UTF_8);try{Path folder=Path.of(secretKeyFile).toAbsolutePath().getParent().resolve("artifacts");Files.createDirectories(folder);Files.setPosixFilePermissions(folder,java.nio.file.attribute.PosixFilePermissions.fromString("rwx------"));Files.write(folder.resolve(artifact.toString()),bytes,StandardOpenOption.CREATE_NEW);Files.setPosixFilePermissions(folder.resolve(artifact.toString()),java.nio.file.attribute.PosixFilePermissions.fromString("rw-------")); }catch(Exception e){throw new WorkspaceDenied(503,"ArtifactStorageUnavailable");}jdbc.update("INSERT INTO ai_artifact(id,owner_user_id,run_id,filename,media_type,byte_size,sha256,storage_key) VALUES(?,?,?,?,?,?,?,?)",artifact,run.get("owner_user_id"),id,args.get("filename"),"text/plain; charset=utf-8",bytes.length,hash(args.get("content").toString()),artifact);result=Map.of("artifactId",artifact.toString(),"filename",args.get("filename"),"byteSize",bytes.length,"sha256",hash(args.get("content").toString()));events.append((UUID)run.get("session_id"),id,UUID.randomUUID(),"artifact.created",result);}
  jdbc.update("INSERT INTO ai_tool_execution(run_id,call_id,resource_id,args_hash,result) VALUES(?,?,?,?,?::jsonb)",id,call,resource,digest,JsonUtils.toJsonString(result));return result;});}
 public Map<String,Object> artifact(UUID id,WorkspacePrincipal.Actor actor){var rows=jdbc.queryForList("SELECT a.*,r.session_id FROM ai_artifact a JOIN ai_run r ON r.id=a.run_id WHERE a.id=? AND a.owner_user_id=? AND a.deleted_at IS NULL",id,actor.userId());if(rows.size()!=1)throw new WorkspaceDenied(404,"ArtifactNotFound");var a=rows.getFirst();conversations.authorizeSession((UUID)a.get("session_id"),actor);return a;}
 public byte[] bytes(Map<String,Object> artifact){try{Path file=Path.of(secretKeyFile).toAbsolutePath().getParent().resolve("artifacts").resolve(artifact.get("storage_key").toString());return Files.readAllBytes(file);}catch(Exception e){throw new WorkspaceDenied(404,"ArtifactNotFound");}}
}
